DWORD ROR13Hash(const char* str) {
    DWORD hash = 0;
    while (*str) {
        hash = (hash >> 13) | (hash << 19);
        hash += *str;
        str++;
    }
    return hash;
}
// ROR13Hash("CreateRemoteThread") = 0x6B8029
